contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount <= address(this).balance);

        uint256 bBefore = c.balanceOf(address(this));
        uint256 rBefore = c.totalRemaining();
        uint256 dBefore = c.totalDistributed();
        bool finishedBefore = c.distributionFinished();
        uint256 vBefore = c.value();

        bool reverted;
        try c.getTokens{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 bAfter = c.balanceOf(address(this));
            uint256 rAfter = c.totalRemaining();
            uint256 dAfter = c.totalDistributed();

            if (!finishedBefore) {
                uint256 expected = amount < vBefore ? amount : vBefore;
                assert(bAfter - bBefore == expected);
                assert(rBefore - rAfter == expected);
                assert(dAfter - dBefore == expected);
                assert(c.value() <= vBefore);
            }
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint256 ethAmount) public payable {
        require(address(this).balance >= ethAmount);

        address caller = address(this);
        uint256 preBal = c.balanceOf(caller);
        uint256 preRemaining = c.totalRemaining();
        uint256 preDistributed = c.totalDistributed();
        uint256 preValue = c.value();
        bool preBlacklisted = c.blacklist(caller);

        c.getTokens{value: ethAmount}();

        uint256 postBal = c.balanceOf(caller);
        uint256 postRemaining = c.totalRemaining();
        uint256 postDistributed = c.totalDistributed();
        uint256 postValue = c.value();
        bool postBlacklisted = c.blacklist(caller);

        uint256 added = min(preValue, preRemaining);

        assert(
            postBal - preBal == added &&
            preRemaining - postRemaining == added &&
            postDistributed - preDistributed == added &&
            preValue - postValue == added / 100000 + (added % 100000 == 0 && added > 0 ? 1 : 0) &&
            (postBlacklisted == true || caller == c.owner())
        );
    }

    function min(uint256 a, uint256 b) internal pure returns (uint256) {
        return a < b ? a : b;
    }
}
